t.script:
async function loadChallenge() {
    const token =
        document.getElementById(
            'jti'
        ).value;

    if (!token) {
        alert('Token required');
        return;
    }

    const response = await fetch(
        `/mobile/challenge/${token}`,
        {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: '{}'
        }
    );

    const data = await response.json();
    console.log(data);
    if (!data.result) {
        alert('Invalid response');
        return;
    }

    if (!data.result.success) {
        alert('Challenge not found');
        return;
    }
    const challenge = data.result.challenge;
    document.getElementById(
        'challenge-detail'
    ).innerHTML = `




                ${challenge.action}



                Status:
                ${challenge.status}




                Approve



                Reject



    `;
}

async function approveChallenge(token) {

    const response = await fetch(
        `/mobile/approve/${token}`,
        {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: '{}'
        }
    );

    const data = await response.json();

    console.log(data);

    alert('Approved');

    loadChallenge();
}

async function rejectChallenge(token) {

    const response = await fetch(
        `/mobile/reject/${token}`,
        {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: '{}'
        }
    );

    const data = await response.json();
    console.log(data);
    alert('Rejected');
    loadChallenge();
}
